<?php require_once 'includes/db.php';$title='Products - '.APP_NAME;$ps=db()->query('SELECT * FROM products WHERE active=1 ORDER BY id DESC')->fetchAll();include 'includes/header.php';?><h1>Products</h1><div class="grid"><?php foreach($ps as $p):?><div class="card"><img src="<?=htmlspecialchars($p['image'])?>"><h3><?=htmlspecialchars($p['name'])?></h3><p><?=htmlspecialchars($p['description'])?></p><div class="price">KES <?=number_format($p['price'],2)?></div><a class="btn" href="product.php?id=<?=$p['id']?>">View Product</a></div><?php endforeach;?></div><?php include 'includes/footer.php';?>